$patch$::jsonb;
    target record;
    graph jsonb;
    node jsonb;
    delta jsonb;
    config jsonb;
    nodes jsonb;
    edges jsonb;
    parameter jsonb;
begin
    for target in select * from automation_trigger
        where workflow_definition is not null
          and workflow_definition::jsonb->>'entryNodeId' = 'smart-create-1'
          and exists (select 1 from jsonb_array_elements(workflow_definition::jsonb->'nodes') n where n->>'id' = 'smart-create-57')
          and exists (select 1 from jsonb_array_elements(workflow_definition::jsonb->'nodes') n where n->>'id' = 'smart-create-62')
          and not exists (select 1 from jsonb_array_elements(workflow_definition::jsonb->'nodes') n where n->>'id' = 'title-generate')
        for update
    loop
        insert into automation_workflow_backup(trigger_id, migration_version, definition)
            values (target.id, 78, to_jsonb(target)) on conflict do nothing;
        graph := target.workflow_definition::jsonb;
        select coalesce(jsonb_agg(e), '[]'::jsonb) into edges
            from jsonb_array_elements(graph->'edges') e
            where not (patch->'replaceEdgeSources' ? (e->>'source'));
        edges := edges || (patch->'edges');
        nodes := '[]'::jsonb;
        for node in select * from jsonb_array_elements(graph->'nodes')
        loop
            delta := patch->'updates'->(node->>'id');
            if delta is not null then
                config := coalesce(node->'config', '{}'::jsonb) || coalesce(delta->'config', '{}'::jsonb);
                node := node || jsonb_build_object('config', config);
            end if;
            if node->>'type' = 'PARAMETERS' then
                for parameter in select * from jsonb_array_elements(patch->'appendParameters')
                loop
                    if not exists (select 1 from jsonb_array_elements(node#>'{config,parameters}') p
                                   where p->>'name' = parameter->>'name') then
                        node := jsonb_set(node, '{config,parameters}',
                                          coalesce(node#>'{config,parameters}', '[]'::jsonb) || jsonb_build_array(parameter));
                    end if;
                end loop;
            end if;
            nodes := nodes || jsonb_build_array(node);
        end loop;
        graph := graph || jsonb_build_object('nodes', nodes || (patch->'addNodes'), 'edges', edges);
        update automation_trigger set workflow_definition = graph::text where id = target.id;
    end loop;
end
